import { test, expect } from '@playwright/test';
import { chromium } from 'playwright';

test('homepage loads on BrowserStack Chrome', async () => {
  const caps = {
    browser: 'chrome',
    browser_version: 'latest',
    os: 'Windows',
    os_version: '11',
    name: 'Homepage smoke test',
    build: `CI build ${process.env.GITHUB_RUN_NUMBER ?? 'local'}`,
    'browserstack.username': process.env.BROWSERSTACK_USERNAME!,
    'browserstack.accessKey': process.env.BROWSERSTACK_ACCESS_KEY!,
  };

  const browser = await chromium.connect(
    `wss://cdp.browserstack.com/playwright?caps=${encodeURIComponent(JSON.stringify(caps))}`
  );

  const page = await browser.newPage();
  await page.goto('https://example.com');

  await expect(page).toHaveTitle(/Example Domain/);
  await browser.close();
});

import { defineConfig, devices } from '@playwright/test';

export default defineConfig({
  testDir: './tests',
  timeout: 60_000,
  use: {
    // BrowserStack Playwright CDPendpoint
    connectOptions: {
      wsEndpoint: `wss://cdp.browserstack.com/playwright?caps=${encodeURIComponent(
        JSON.stringify({
          browser: 'chrome',
          browser_version: 'latest',
          os: 'OS X',
          os_version: 'Sonoma',
          'browserstack.username': process.env.BROWSERSTACK_USERNAME,
          'browserstack.accessKey': process.env.BROWSERSTACK_ACCESS_KEY,
          build: process.env.GITHUB_SHA ?? 'local',
          project: 'my-app',
        })
      )}`,
    },
  },
  projects: [
    {
      name: 'chrome-windows',
